// Strict classifier. Reads the selected scenario/variant from the Set node (no hardcoding)
// and categorizes the model output. It forwards an operation/target ONLY for exactly one valid
// propose_action tool call. Every other case is forwarded as a non-actionable proposal with a
// model_parse label, so the provider cannot mediate it and no effect can occur. The provider
// still re-derives its own trusted decision; model_parse is audit-only.
const sc = $('Scenario + Prompt').first().json;
const scenario_id = sc.scenario_id;
const prompt_variant_id = sc.prompt_variant_id;
const model = sc.model;

const msg = ($input.first().json.message) || {};
const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
const content = (msg.content || '').toString();

let model_parse;
let proposal = {};
if (calls.length > 1) {
  model_parse = 'multiple_calls';
} else if (calls.length === 1) {
  const fn = (calls[0] && calls[0].function) || {};
  if (fn.name !== 'propose_action') {
    model_parse = 'unknown_tool';
  } else {
    let args = fn.arguments;
    if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = null; } }
    if (!args || typeof args !== 'object' || typeof args.operation !== 'string' || typeof args.target !== 'string') {
      model_parse = 'malformed_args';
    } else {
      model_parse = 'tool_call';
      proposal = { operation: args.operation, target: args.target, claimed_class: (typeof args.claimed_class === 'string' ? args.claimed_class : null) };
    }
  }
} else {
  // No tool call. Empty content is a no-call; non-empty content is text with no call. Neither is
  // treated as an explicit refusal (this demo exposes no refusal tool).
  model_parse = (content.trim() === '') ? 'no_call' : 'no_call_text';
}

const toolName = calls.length ? (((calls[0] || {}).function || {}).name || '(unnamed)') : '(none)';
const meta = ('model=' + model + ' think=false temp=0 seed=42 ollama_tool_calls=' + calls.length + ' tool=' + toolName).slice(0, 2000);

return [{ json: { scenario_id, prompt_variant_id, model_metadata: meta, model_parse, proposal } }];
